<div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><div class="card"><h1>Welcome, <?=e($_SESSION['user']['name'])?></h1><p class="muted">Teacher dashboard</p></div><div class="grid" style="margin-top:18px"><div class='card'><div class='muted'>My Classes</div><div class='stat'><?=e(metric($pdo,"SELECT COUNT(*) FROM teacher_classes tc JOIN teachers t ON t.id=tc.teacher_id WHERE t.user_id=?",[$_SESSION['user']['id']]))?></div></div><div class='card'><div class='muted'>My Subjects</div><div class='stat'><?=e(metric($pdo,"SELECT COUNT(*) FROM teacher_subjects ts JOIN teachers t ON t.id=ts.teacher_id WHERE t.user_id=?",[$_SESSION['user']['id']]))?></div></div><div class='card'><div class='muted'>Assignments</div><div class='stat'><?=e(metric($pdo,"SELECT COUNT(*) FROM assignments a JOIN teachers t ON t.id=a.teacher_id WHERE t.user_id=?",[$_SESSION['user']['id']]))?></div></div><div class='card'><div class='muted'>Unread Notifications</div><div class='stat'><?=e(metric($pdo,"SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0",[$_SESSION['user']['id']]))?></div></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>